package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
)

func main() {
	src := `
package foo

import "go/ast"

func check(x interface{}) {
	switch x.(type) {
	case ast.Expr:
		_ = x
	case *ast.BasicLit:
		_ = x
	}
}
`
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "foo.go", src, 0)
	if err != nil {
		panic(err)
	}

	cfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", nil),
	}
	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
	}
	pkg, err := cfg.Check("foo", fset, []*ast.File{f}, info)
	if err != nil {
		fmt.Println("Type check error:", err)
		return
	}
	fmt.Println("Package:", pkg.Name())
	fmt.Println("Type check OK")
}
EOF
cd /tmp/testimport2 && go build . && ./main

