package framework

import (
	"fmt"
	"sort"
	"strings"
)

// Registry stores all registered checkers
type Registry struct {
	checkers map[string]*CheckerInfo
	order    []string
}

// NewRegistry creates a new registry
func NewRegistry() *Registry {
	return &Registry{
		checkers: make(map[string]*CheckerInfo),
	}
}

// Register adds a checker to the registry
func (r *Registry) Register(info *CheckerInfo) {
	r.checkers[info.Name] = info
	r.order = append(r.order, info.Name)
	sort.Strings(r.order)
}

// AllCheckers returns all checker infos sorted by name
func (r *Registry) AllCheckers() []*CheckerInfo {
	result := make([]*CheckerInfo, 0, len(r.order))
	for _, name := range r.order {
		result = append(result, r.checkers[name])
	}
	return result
}

// Get returns a checker info by name
func (r *Registry) Get(name string) (*CheckerInfo, bool) {
	c, ok := r.checkers[name]
	return c, ok
}

// SelectCheckers returns checkers matching the enable/disable rules
func (r *Registry) SelectCheckers(enable, disable string, enableAll bool) ([]*CheckerInfo, error) {
	all := r.AllCheckers()

	var enabled map[string]bool

	if enableAll {
		enabled = make(map[string]bool)
		for _, c := range all {
			enabled[c.Name] = true
		}
	} else if enable == "" {
		enabled = make(map[string]bool)
	} else {
		enabled = make(map[string]bool)
		for _, item := range strings.Split(enable, ",") {
			item = strings.TrimSpace(item)
			if item == "" {
				continue
			}
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				for _, c := range all {
					if hasTag(c.Tags, tag) {
						enabled[c.Name] = true
					}
				}
			} else {
				if _, ok := r.checkers[item]; !ok {
					// Unknown checker - ignore? or error?
					// The original tool prints debug message
				}
				enabled[item] = true
			}
		}
	}

	if disable != "" {
		for _, item := range strings.Split(disable, ",") {
			item = strings.TrimSpace(item)
			if item == "" {
				continue
			}
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				for _, c := range all {
					if hasTag(c.Tags, tag) {
						delete(enabled, c.Name)
					}
				}
			} else {
				delete(enabled, item)
			}
		}
	}

	result := make([]*CheckerInfo, 0)
	for _, name := range r.order {
		if enabled[name] {
			result = append(result, r.checkers[name])
		}
	}

	if len(result) == 0 {
		return nil, fmt.Errorf("empty checkers set selected")
	}

	return result, nil
}

func hasTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}
GOEOF

