package main

import (
	"fmt"
	"os"
)

const version = "v0.0.0-SNAPSHOT"

var commands = []string{"check", "doc", "help", "version"}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Println("no args provided")
		return
	}

	switch args[0] {
	case "version":
		runVersion()
	case "doc":
		os.Exit(runDoc(args[1:]))
	case "check":
		os.Exit(runCheck(args[1:]))
	case "help":
		runHelp()
	default:
		cmd := args[0]
		suggestion := findSuggestion(cmd)
		if suggestion != "" {
			fmt.Printf("%q unknown command, did you mean %q?\n", cmd, suggestion)
		} else {
			fmt.Printf("%q unknown command\n", cmd)
		}
		fmt.Printf("Run \"go-critic help\" for usage.\n\n")
		fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
	}
}

func levenshtein(s1, s2 string) int {
	m, n := len(s1), len(s2)
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
		dp[i][0] = i
	}
	for j := 0; j <= n; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			if s1[i-1] == s2[j-1] {
				dp[i][j] = dp[i-1][j-1]
			} else {
				dp[i][j] = 1 + min3(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
			}
		}
	}
	return dp[m][n]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func findSuggestion(cmd string) string {
	const maxDist = 2
	best := ""
	bestDist := maxDist + 1
	for _, c := range commands {
		d := levenshtein(cmd, c)
		if d < bestDist {
			bestDist = d
			best = c
