package checkers

// CheckerInfo contains metadata about a checker
type CheckerInfo struct {
	Name        string
	Tags        []string
	Summary     string
	Before      string // Non-compliant code example
	After       string // Compliant code example  
	Note        string // Additional note
	Params      []Param
}

