func registerChecker(info *CheckerInfo) {
	allCheckers = append(allCheckers, info)
}

// GetAll returns all registered checkers sorted by name
func GetAll() []*CheckerInfo {
	return allCheckers
}

// Get finds a checker by name
func Get(name string) *CheckerInfo {
	for _, c := range allCheckers {
		if c.Name == name {
			return c
		}
	}
	return nil
}
