package main

import (
	"flag"
	"fmt"
	"os"
	"sort"
	"strings"

	"go-critic-reimpl/checkers"
)

func runDoc(args []string) int {
	fs := flag.NewFlagSet("doc", flag.ContinueOnError)
	fs.Usage = func() {
		fmt.Println("Usage of go-critic:")
		fmt.Println("flag: help requested")
	}
	if err := fs.Parse(args); err != nil {
		if err == flag.ErrHelp {
			return 0
		}
		return 1
	}

	remaining := fs.Args()
	if len(remaining) == 0 {
		// List all checkers
		all := checkers.GetAll()
		sort.Slice(all, func(i, j int) bool {
			return all[i].Name < all[j].Name
		})
		for _, c := range all {
			fmt.Printf("%s [%s]\n", c.Name, strings.Join(c.Tags, " "))
		}
		return 0
	}

	// Show doc for specific checker
	name := remaining[0]
	c := checkers.Get(name)
	if c == nil {
		fmt.Fprintf(os.Stderr, "checker with name %q not found\n", name)
		return 1
	}

	printCheckerDoc(c)
	return 0
}

func printCheckerDoc(c *checkers.CheckerInfo) {
	fmt.Printf("%s checker documentation\n", c.Name)
	fmt.Printf("URL: https://github.com/go-critic/go-critic/checkers\n")
	fmt.Printf("Tags: [%s]\n", strings.Join(c.Tags, " "))
	fmt.Println()

	// Summary
	fmt.Println(c.Summary)
	fmt.Println()

	// Note before code examples (if any)
	if c.Before != "" || c.After != "" {
		if c.Note != "" && !strings.HasPrefix(c.Note, "See ") && !strings.HasPrefix(c.Note, "http") {
			fmt.Println(c.Note)
			fmt.Println()
		}
		fmt.Println("Non-compliant code:")
		fmt.Println(c.Before)
		fmt.Println()
		fmt.Println("Compliant code:")
		fmt.Println(c.After)
		fmt.Println()
		// Note after code examples
		if c.Note != "" && (strings.HasPrefix(c.Note, "See ") || strings.HasPrefix(c.Note, "http")) {
			fmt.Println(c.Note)
			fmt.Println()
		}
	} else if c.Note != "" {
		fmt.Println(c.Note)
		fmt.Println()
	}

	// Parameters
	if len(c.Params) > 0 {
		fmt.Println("Checker parameters:")
		for _, p := range c.Params {
			var defaultStr string
			switch v := p.Default.(type) {
			case bool:
				if v {
					defaultStr = "true"
				} else {
					defaultStr = "false"
				}
			case int:
				defaultStr = fmt.Sprintf("%d", v)
			case string:
				defaultStr = v
			}
			fmt.Printf("  -@%s.%s %s\n", c.Name, p.Name, p.Type)
			fmt.Printf("    \t%s (default %s)\n", p.Doc, defaultStr)
		}
	}
}
