package linter

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// Package represents a loaded Go package
type Package struct {
	ImportPath string
	Name       string
	Dir        string
	Files      []*ast.File
	Fset       *token.FileSet
	TypesInfo  *types.Info
	TypesPkg   *types.Package
	IsTest     bool
	FileNames  []string // actual file paths
}

// listPackage is the JSON structure from `go list -json`
type listPackage struct {
	Dir          string   `json:"Dir"`
	ImportPath   string   `json:"ImportPath"`
	Name         string   `json:"Name"`
	GoFiles      []string `json:"GoFiles"`
	TestGoFiles  []string `json:"TestGoFiles"`
	XTestGoFiles []string `json:"XTestGoFiles"`
	CgoFiles     []string `json:"CgoFiles"`
	CompiledGoFiles []string `json:"CompiledGoFiles"`
	Root         string   `json:"Root"`
	ForTest      string   `json:"ForTest"`
	Imports      []string `json:"Imports"`
	Deps         []string `json:"Deps"`
}

// LoadPackages loads Go packages matching the given patterns
func LoadPackages(patterns []string, checkTests bool) ([]*Package, error) {
	// Run go list -json -test to get package info
	args := []string{"list", "-json", "-test", "-e"}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	out, err := cmd.Output()
	if err != nil {
		// Some packages may fail, that's OK
		if exitErr, ok := err.(*exec.ExitError); ok {
			_ = exitErr
			// Continue with partial output
		} else {
			return nil, fmt.Errorf("go list failed: %v", err)
		}
	}

	// Parse multiple JSON objects
	var pkgInfos []listPackage
	decoder := json.NewDecoder(strings.NewReader(string(out)))
	for decoder.More() {
		var pkg listPackage
		if err := decoder.Decode(&pkg); err != nil {
			continue
		}
		pkgInfos = append(pkgInfos, pkg)
	}

	// Select packages to check
	// We want the "[test]" variants but NOT the ".test" binary packages
	// Specifically: "pkg [pkg.test]" and "pkg_test [pkg.test]"
	// But exclude the "pkg.test" (binary) package
	var toCheck []listPackage
	for _, pkg := range pkgInfos {
		// Skip the binary .test package
		if strings.HasSuffix(pkg.ImportPath, ".test") && pkg.Name == "main" {
			continue
		}
		// Skip non-test variant if test variant exists
		// (we'll use the [test] variant which includes TestGoFiles)
		if !strings.Contains(pkg.ImportPath, "[") {
			// Check if there's a test variant
			hasTestVariant := false
			for _, p2 := range pkgInfos {
				if strings.Contains(p2.ImportPath, "[") &&
					strings.Contains(p2.ImportPath, pkg.ImportPath) &&
					!strings.HasSuffix(p2.ImportPath, ".test") {
					hasTestVariant = true
					break
				}
			}
			if hasTestVariant {
				continue // Use the test variant instead
			}
		}
		toCheck = append(toCheck, pkg)
	}

	var result []*Package
	for _, pkgInfo := range toCheck {
		pkg, err := loadPackage(pkgInfo, checkTests)
		if err != nil {
			// Skip packages that fail to load
			fmt.Fprintf(os.Stderr, "error loading package %s: %v\n", pkgInfo.ImportPath, err)
			continue
		}
		if pkg != nil {
			result = append(result, pkg)
		}
	}

	return result, nil
}

func loadPackage(info listPackage, checkTests bool) (*Package, error) {
	fset := token.NewFileSet()

	// Determine which files to load
	var fileNames []string
	isTestPkg := strings.Contains(info.ImportPath, "[") && !strings.HasSuffix(info.ImportPath, ".test")

	if isTestPkg {
		// This is a test variant package
		if strings.HasSuffix(info.Name, "_test") {
			// External test package: GoFiles contains XTestGoFiles
			for _, f := range info.GoFiles {
				if !strings.HasPrefix(f, "/") {
					fileNames = append(fileNames, filepath.Join(info.Dir, f))
				} else {
					fileNames = append(fileNames, f)
				}
			}
		} else {
			// Internal test package: GoFiles contains GoFiles + TestGoFiles
			for _, f := range info.GoFiles {
				if !strings.HasPrefix(f, "/") {
					fileNames = append(fileNames, filepath.Join(info.Dir, f))
				} else {
					fileNames = append(fileNames, f)
				}
			}
		}
	} else {
		for _, f := range info.GoFiles {
			fileNames = append(fileNames, filepath.Join(info.Dir, f))
		}
	}

	if len(fileNames) == 0 {
		return nil, nil
	}

	// Parse files
	var files []*ast.File
	var actualFileNames []string
	for _, fname := range fileNames {
		// Filter test files if not checking tests
		if !checkTests && strings.HasSuffix(fname, "_test.go") {
			continue
		}
		f, err := parser.ParseFile(fset, fname, nil, parser.ParseComments)
		if err != nil {
			// Skip files with parse errors
			continue
		}
		files = append(files, f)
		actualFileNames = append(actualFileNames, fname)
	}

	if len(files) == 0 {
		return nil, nil
	}

	// Type check
	typesInfo := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Implicits:  make(map[ast.Node]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
		Scopes:     make(map[ast.Node]*types.Scope),
	}

	cfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", nil),
		Error:    func(err error) {}, // Ignore type errors
	}

	typesPkg, _ := cfg.Check(info.Dir, fset, files, typesInfo)

	pkg := &Package{
		ImportPath: info.ImportPath,
		Name:       info.Name,
		Dir:        info.Dir,
		Files:      files,
		Fset:       fset,
		TypesInfo:  typesInfo,
		TypesPkg:   typesPkg,
		IsTest:     isTestPkg,
		FileNames:  actualFileNames,
	}

	return pkg, nil
}
