# Plus all other checkers that users may enable

# Given the massive scope, let me focus on implementing the actual checkers
# Each checker needs to walk the AST and report warnings

# Let me write the check.go file first to establish the structure

cat > /workspace/src/cmd/gocritic/check.go << 'GOEOF'
package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"

	"go-critic-reimpl/checkers"
	"go-critic-reimpl/linter"
)

const defaultEnable = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

func runCheck(args []string) int {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	// Checker params (registered with -@ prefix)
	checkerParams := registerCheckerParams(fs)

	// Main flags
	var (
		enable       string
		disable      string
		enableAll    bool
		checkTests   bool
		checkGenerated bool
		verbose      bool
		exitCode     int
		goVersion    string
		concurrency  int
		shorterErr   bool
		cpuprofile   string
		memprofile   string
	)

	fs.StringVar(&enable, "enable", defaultEnable, "comma-separated list of enabled checkers. Can include #tags")
	fs.StringVar(&disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	fs.BoolVar(&enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.BoolVar(&checkTests, "checkTests", true, "whether to check test files")
	fs.BoolVar(&checkGenerated, "checkGenerated", false, "whether to check generated files")
	fs.BoolVar(&verbose, "v", false, "whether to print output useful during linter debugging")
	fs.IntVar(&exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
	fs.StringVar(&goVersion, "go", "", "select the Go version to target. Leave as string for the latest")
	fs.IntVar(&concurrency, "concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	fs.BoolVar(&shorterErr, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.StringVar(&cpuprofile, "cpuprofile", "", "write CPU profile to the specified file")
	fs.StringVar(&memprofile, "memprofile", "", "write memory profile to the specified file")

	if err := fs.Parse(args); err != nil {
		if err == flag.ErrHelp {
			fmt.Fprintf(os.Stderr, "parse args: flag: help requested\n")
			return 1
		}
		fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
		return 1
	}

	// Select enabled checkers
	allCheckers := checkers.GetAll()

	if verbose {
		// Print debug info for each checker
		for _, c := range allCheckers {
			enabled := isCheckerEnabled(c, enable, disable, enableAll)
			if enabled {
				fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", c.Name)
			} else {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", c.Name)
			}
		}
	}

	// Build list of enabled checkers
	var enabledCheckers []*checkers.CheckerInfo
	for _, c := range allCheckers {
		if isCheckerEnabled(c, enable, disable, enableAll) {
			enabledCheckers = append(enabledCheckers, c)
		}
	}

	if len(enabledCheckers) == 0 {
		fmt.Fprintf(os.Stderr, "init checkers: empty checkers set selected\n")
		return 1
	}

	// Get package patterns
	patterns := fs.Args()
	if len(patterns) == 0 {
		return 0
	}

	// Determine shorterErrLocation config
	goroot := ""
	gopath := ""
	if shorterErr {
		goroot = os.Getenv("GOROOT")
		gopath = os.Getenv("GOPATH")
	}

	// Load packages
	pkgs, err := linter.LoadPackages(patterns, checkTests, goVersion)
	if err != nil {
		fmt.Fprintf(os.Stderr, "load packages: %v\n", err)
		return 1
	}

	// Run checkers
	hasWarnings := false
	for _, pkg := range pkgs {
		if verbose {
			fmt.Fprintf(os.Stderr, "\tdebug: checking %q package (%d files)\n", pkg.ImportPath, len(pkg.Files))
		}

		for _, f := range pkg.Files {
			fname := pkg.Fset.File(f.Pos()).Name()

			// Skip generated files if not checking them
			if !checkGenerated && isGeneratedFile(f) {
				continue
			}

			for _, c := range enabledCheckers {
				warnings := runChecker(c, pkg, f, checkerParams)
				for _, w := range warnings {
					pos := pkg.Fset.Position(w.Pos)
					path := pos.Filename

					// Make path relative
					if rel, err := filepath.Rel(".", path); err == nil {
						path = rel
					}

					// Apply shorter error location
					if shorterErr {
						if goroot != "" && strings.HasPrefix(path, goroot) {
							path = "$GOROOT" + path[len(goroot):]
						} else if gopath != "" && strings.HasPrefix(path, gopath) {
							path = "$GOPATH" + path[len(gopath):]
						}
					}

					// If still not relative, make it relative or use ./
					if !strings.HasPrefix(path, "$") && !strings.HasPrefix(path, "/") && !strings.HasPrefix(path, ".") {
						path = "./" + path
					}

					fmt.Printf("%s:%d:%d: %s: %s\n", path, pos.Line, pos.Column, c.Name, w.Text)
					hasWarnings = true
				}
			}
		}
	}

	if hasWarnings {
		return exitCode
	}
	return 0
}

// isCheckerEnabled checks if a checker should be enabled given the enable/disable flags
func isCheckerEnabled(c *checkers.CheckerInfo, enable, disable string, enableAll bool) bool {
	var enabled bool

	if enableAll {
		enabled = true
	} else {
		for _, item := range strings.Split(enable, ",") {
			item = strings.TrimSpace(item)
			if item == "" {
				continue
			}
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				if hasTag(c.Tags, tag) {
					enabled = true
				}
			} else if item == c.Name {
				enabled = true
			}
		}
	}

	if enabled && disable != "" {
		for _, item := range strings.Split(disable, ",") {
			item = strings.TrimSpace(item)
			if item == "" {
				continue
			}
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				if hasTag(c.Tags, tag) {
					enabled = false
				}
			} else if item == c.Name {
				enabled = false
			}
		}
	}

	return enabled
}

func hasTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}

// Warning represents a checker finding
type Warning struct {
	Pos  token.Pos
	Text string
}

// CheckerParams holds parameter values for all checkers
type CheckerParams struct {
	CaptLocalParamsOnly        bool
	CommentedOutCodeMinLength  int
	ElseifSkipBalanced         bool
	HugeParamSizeThreshold     int
	IfElseChainMinThreshold    int
	NestingReduceBodyWidth     int
	RangeExprCopySizeThreshold int
	RangeExprCopySkipTestFuncs bool
	RangeValCopySizeThreshold  int
	RangeValCopySkipTestFuncs  bool
	RuleguardDebug             string
	RuleguardDisable           string
	RuleguardEnable            string
	RuleguardFailOn            string
	RuleguardFailOnError       bool
	RuleguardRules             string
	TooManyResultsMax          int
	TruncateCmpSkipArchDep     bool
	UnderefSkipRecvDeref       bool
	UnnamedResultCheckExported bool
}

func registerCheckerParams(fs *flag.FlagSet) *CheckerParams {
	p := &CheckerParams{}

	fs.BoolVar(&p.CaptLocalParamsOnly, "@captLocal.paramsOnly", true, "whether to restrict checker to params only")
	fs.IntVar(&p.CommentedOutCodeMinLength, "@commentedOutCode.minLength", 15, "min length of the comment that triggers a warning")
	fs.BoolVar(&p.ElseifSkipBalanced, "@elseif.skipBalanced", true, "whether to skip balanced if-else pairs")
	fs.IntVar(&p.HugeParamSizeThreshold, "@hugeParam.sizeThreshold", 80, "size in bytes that makes the warning trigger")
	fs.IntVar(&p.IfElseChainMinThreshold, "@ifElseChain.minThreshold", 2, "min number of if-else blocks that makes the warning trigger")
	fs.IntVar(&p.NestingReduceBodyWidth, "@nestingReduce.bodyWidth", 5, "min number of statements inside a branch to trigger a warning")
	fs.IntVar(&p.RangeExprCopySizeThreshold, "@rangeExprCopy.sizeThreshold", 512, "size in bytes that makes the warning trigger")
	fs.BoolVar(&p.RangeExprCopySkipTestFuncs, "@rangeExprCopy.skipTestFuncs", true, "whether to check test functions")
	fs.IntVar(&p.RangeValCopySizeThreshold, "@rangeValCopy.sizeThreshold", 128, "size in bytes that makes the warning trigger")
	fs.BoolVar(&p.RangeValCopySkipTestFuncs, "@rangeValCopy.skipTestFuncs", true, "whether to check test functions")
	fs.StringVar(&p.RuleguardDebug, "@ruleguard.debug", "", "enable debug for the specified named rules group")
	fs.StringVar(&p.RuleguardDisable, "@ruleguard.disable", "", "comma-separated list of disabled groups or skip empty to enable everything")
	fs.StringVar(&p.RuleguardEnable, "@ruleguard.enable", "<all>", "comma-separated list of enabled groups or skip empty to enable everything")
	fs.StringVar(&p.RuleguardFailOn, "@ruleguard.failOn", "", "Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
