package linter

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"sort"
	"strings"
	"unicode"
)

// Helper to create a warning
func warn(pos token.Pos, format string, args ...interface{}) Warning {
	return Warning{Pos: pos, Text: fmt.Sprintf(format, args...)}
}

// Helper to get the string representation of a node
func nodeString(fset *token.FileSet, node ast.Node) string {
	start := fset.Position(node.Pos())
	end := fset.Position(node.End())
	_ = start
	_ = end
	// We'd need the source to get exact text, use a simplified approach
	return formatNode(node)
}

func formatNode(node ast.Node) string {
	switch n := node.(type) {
	case *ast.Ident:
		return n.Name
	case *ast.BasicLit:
		return n.Value
	case *ast.SelectorExpr:
		return formatNode(n.X) + "." + n.Sel.Name
	case *ast.CallExpr:
		args := make([]string, len(n.Args))
		for i, a := range n.Args {
			args[i] = formatNode(a)
		}
		ellipsis := ""
		if n.Ellipsis != token.NoPos {
			ellipsis = "..."
		}
		return formatNode(n.Fun) + "(" + strings.Join(args, ", ") + ellipsis + ")"
	case *ast.IndexExpr:
		return formatNode(n.X) + "[" + formatNode(n.Index) + "]"
	case *ast.SliceExpr:
		low, high, max3 := "", "", ""
		if n.Low != nil {
			low = formatNode(n.Low)
		}
		if n.High != nil {
			high = formatNode(n.High)
		}
		if n.Max != nil {
			max3 = ":" + formatNode(n.Max)
		}
		return formatNode(n.X) + "[" + low + ":" + high + max3 + "]"
	case *ast.StarExpr:
		return "*" + formatNode(n.X)
	case *ast.UnaryExpr:
		return n.Op.String() + formatNode(n.X)
	case *ast.BinaryExpr:
		return formatNode(n.X) + " " + n.Op.String() + " " + formatNode(n.Y)
	case *ast.ParenExpr:
		return "(" + formatNode(n.X) + ")"
	case *ast.TypeAssertExpr:
		if n.Type == nil {
			return formatNode(n.X) + ".(type)"
		}
		return formatNode(n.X) + ".(" + formatNode(n.Type) + ")"
	case *ast.CompositeLit:
		if n.Type != nil {
			elts := make([]string, len(n.Elts))
			for i, e := range n.Elts {
				elts[i] = formatNode(e)
			}
			return formatNode(n.Type) + "{" + strings.Join(elts, ", ") + "}"
		}
		return "{...}"
	case *ast.KeyValueExpr:
		return formatNode(n.Key) + ": " + formatNode(n.Value)
	case *ast.ArrayType:
		if n.Len == nil {
			return "[]" + formatNode(n.Elt)
		}
		return "[" + formatNode(n.Len) + "]" + formatNode(n.Elt)
	case *ast.MapType:
		return "map[" + formatNode(n.Key) + "]" + formatNode(n.Value)
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.FuncType:
		return "func(...)"
	case *ast.AssignStmt:
		lhs := make([]string, len(n.Lhs))
		rhs := make([]string, len(n.Rhs))
		for i, e := range n.Lhs {
			lhs[i] = formatNode(e)
		}
		for i, e := range n.Rhs {
			rhs[i] = formatNode(e)
		}
		return strings.Join(lhs, ", ") + " " + n.Tok.String() + " " + strings.Join(rhs, ", ")
	case nil:
		return ""
	default:
		return fmt.Sprintf("%T", n)
	}
}

// exprEqual checks if two AST expressions are syntactically equal
func exprEqual(a, b ast.Expr) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	switch x := a.(type) {
	case *ast.Ident:
		if y, ok := b.(*ast.Ident); ok {
			return x.Name == y.Name
		}
	case *ast.BasicLit:
		if y, ok := b.(*ast.BasicLit); ok {
			return x.Kind == y.Kind && x.Value == y.Value
		}
	case *ast.SelectorExpr:
		if y, ok := b.(*ast.SelectorExpr); ok {
			return exprEqual(x.X, y.X) && x.Sel.Name == y.Sel.Name
		}
	case *ast.IndexExpr:
		if y, ok := b.(*ast.IndexExpr); ok {
			return exprEqual(x.X, y.X) && exprEqual(x.Index, y.Index)
		}
	case *ast.StarExpr:
		if y, ok := b.(*ast.StarExpr); ok {
			return exprEqual(x.X, y.X)
		}
	case *ast.UnaryExpr:
		if y, ok := b.(*ast.UnaryExpr); ok {
			return x.Op == y.Op && exprEqual(x.X, y.X)
		}
	case *ast.BinaryExpr:
		if y, ok := b.(*ast.BinaryExpr); ok {
			return x.Op == y.Op && exprEqual(x.X, y.X) && exprEqual(x.Y, y.Y)
		}
	case *ast.ParenExpr:
		if y, ok := b.(*ast.ParenExpr); ok {
			return exprEqual(x.X, y.X)
		}
	case *ast.CallExpr:
		if y, ok := b.(*ast.CallExpr); ok {
			if !exprEqual(x.Fun, y.Fun) || len(x.Args) != len(y.Args) {
				return false
			}
			for i := range x.Args {
				if !exprEqual(x.Args[i], y.Args[i]) {
					return false
				}
			}
			return true
		}
	case *ast.SliceExpr:
		if y, ok := b.(*ast.SliceExpr); ok {
			return exprEqual(x.X, y.X) && exprEqual(x.Low, y.Low) && exprEqual(x.High, y.High)
		}
	}
	return false
}

// stmtEqual checks if two statements are syntactically equal
func stmtEqual(a, b ast.Stmt) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	switch x := a.(type) {
	case *ast.ExprStmt:
		if y, ok := b.(*ast.ExprStmt); ok {
			return exprEqual(x.X, y.X)
		}
	case *ast.ReturnStmt:
		if y, ok := b.(*ast.ReturnStmt); ok {
			if len(x.Results) != len(y.Results) {
				return false
			}
			for i := range x.Results {
				if !exprEqual(x.Results[i], y.Results[i]) {
					return false
				}
			}
			return true
		}
	case *ast.AssignStmt:
		if y, ok := b.(*ast.AssignStmt); ok {
			if x.Tok != y.Tok || len(x.Lhs) != len(y.Lhs) || len(x.Rhs) != len(y.Rhs) {
				return false
			}
			for i := range x.Lhs {
				if !exprEqual(x.Lhs[i], y.Lhs[i]) {
					return false
				}
			}
			for i := range x.Rhs {
				if !exprEqual(x.Rhs[i], y.Rhs[i]) {
					return false
				}
			}
			return true
		}
	}
	// Compare by string representation as fallback
	return fmt.Sprintf("%T %v", a, a) == fmt.Sprintf("%T %v", b, b)
}

// blockEqual checks if two blocks are syntactically equal
func blockEqual(a, b *ast.BlockStmt) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	if len(a.List) != len(b.List) {
		return false
	}
	for i := range a.List {
		if !stmtEqual(a.List[i], b.List[i]) {
			return false
		}
	}
	return true
}

// isIdent checks if an expression is a specific identifier
func isIdent(expr ast.Expr, name string) bool {
	id, ok := expr.(*ast.Ident)
	return ok && id.Name == name
}

// isSelector checks if an expression is pkg.name
func isSelector(expr ast.Expr, pkg, name string) bool {
	sel, ok := expr.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	return isIdent(sel.X, pkg) && sel.Sel.Name == name
}

// isCallExpr checks if the expression is a call to pkg.func
func isCallTo(expr ast.Expr, pkg, name string) (*ast.CallExpr, bool) {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return nil, false
	}
	if isSelector(call.Fun, pkg, name) {
		return call, true
	}
	return nil, false
}

// getCallFunc returns package and function name for a call expression
func getCallPkgFunc(call *ast.CallExpr) (pkg, name string, ok bool) {
	sel, isSel := call.Fun.(*ast.SelectorExpr)
	if !isSel {
		return "", "", false
	}
	id, isId := sel.X.(*ast.Ident)
	if !isId {
		return "", "", false
	}
	return id.Name, sel.Sel.Name, true
}

// isBasicLit checks if expr is a basic literal with the given kind and value
func isBasicLit(expr ast.Expr, kind token.Token, value string) bool {
	lit, ok := expr.(*ast.BasicLit)
	return ok && lit.Kind == kind && lit.Value == value
}

// isIntLit checks if expr is an integer literal
func isIntLit(expr ast.Expr, value string) bool {
	return isBasicLit(expr, token.INT, value)
}

// isStringLit checks if expr is a string literal
func isStringLit(expr ast.Expr) bool {
	_, ok := expr.(*ast.BasicLit)
	return ok
}

// visitStmts calls fn for every statement in a list
func visitStmts(stmts []ast.Stmt, fn func(ast.Stmt) bool) {
	for _, s := range stmts {
		if !fn(s) {
			return
		}
	}
}

// ====== CHECKER IMPLEMENTATIONS ======

// appendAssign: Detects suspicious append result assignments
func checkAppendAssign(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN {
			return true
		}

		for i := range assign.Lhs {
			if i >= len(assign.Rhs) {
				break
			}
			call, ok := assign.Rhs[i].(*ast.CallExpr)
			if !ok {
				continue
			}
			if !isIdent(call.Fun, "append") {
				continue
			}
			if len(call.Args) < 1 {
				continue
			}
			// Check if LHS and first arg of append are different
			lhs := assign.Lhs[i]
			firstArg := call.Args[0]
			if !exprEqual(lhs, firstArg) {
				// Suspicious: p.positives = append(p.negatives, ...)
				warnings = append(warnings, warn(assign.Pos(),
					"suspicious append result assignment"))
			}
		}
		return true
	})

	return warnings
}

// appendCombine: Detects append chains to the same slice
func checkAppendCombine(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	checkBlock := func(stmts []ast.Stmt) {
		for i := 0; i+1 < len(stmts); i++ {
			assign1, ok1 := stmts[i].(*ast.AssignStmt)
			assign2, ok2 := stmts[i+1].(*ast.AssignStmt)
			if !ok1 || !ok2 {
				continue
			}
			if assign1.Tok != token.ASSIGN || assign2.Tok != token.ASSIGN {
				continue
			}
			if len(assign1.Lhs) != 1 || len(assign1.Rhs) != 1 {
				continue
			}
			if len(assign2.Lhs) != 1 || len(assign2.Rhs) != 1 {
				continue
			}
			call1, ok := assign1.Rhs[0].(*ast.CallExpr)
			if !ok || !isIdent(call1.Fun, "append") {
				continue
			}
			call2, ok := assign2.Rhs[0].(*ast.CallExpr)
			if !ok || !isIdent(call2.Fun, "append") {
				continue
			}
			// Check if both are appending to the same slice
			if !exprEqual(assign1.Lhs[0], assign2.Lhs[0]) {
				continue
			}
			if len(call1.Args) < 1 || len(call2.Args) < 1 {
				continue
			}
			if !exprEqual(assign1.Lhs[0], call1.Args[0]) {
				continue
			}
			if !exprEqual(assign2.Lhs[0], call2.Args[0]) {
				continue
			}
			warnings = append(warnings, warn(assign2.Pos(),
				"can combine chain of append calls into one"))
		}
	}

	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.BlockStmt:
			checkBlock(x.List)
		case *ast.CaseClause:
			checkBlock(x.Body)
		}
		return true
	})

	return warnings
}

// argOrder: Detects suspicious argument order
func checkArgOrder(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	// Functions where argument order matters (first arg should be "haystack")
	suspiciousFuncs := map[string]bool{
		"strings.HasPrefix":  true,
		"strings.HasSuffix":  true,
		"strings.Contains":   true,
		"strings.EqualFold":  true,
		"strings.Count":      true,
		"strings.Index":      true,
		"strings.LastIndex":  true,
		"strings.TrimPrefix": true,
		"strings.TrimSuffix": true,
		"bytes.HasPrefix":    true,
		"bytes.HasSuffix":    true,
		"bytes.Contains":     true,
		"bytes.EqualFold":    true,
		"bytes.Count":        true,
		"bytes.Index":        true,
		"bytes.LastIndex":    true,
	}

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}

		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg {
			return true
		}

		key := pkg + "." + name
		if !suspiciousFuncs[key] {
			return true
		}

		// Check if first arg is a short literal and second is a variable
		first := call.Args[0]
		second := call.Args[1]

		firstIsLit := isStringLiteral(first)
		secondIsVar := isSimpleVar(second)

		if firstIsLit && secondIsVar {
			// Suspicious: the literal is in the "needle" position
			firstStr := ""
			if lit, ok := first.(*ast.BasicLit); ok {
				firstStr = lit.Value
			}
			secondStr := formatNode(second)
			warnings = append(warnings, warn(call.Pos(),
				"%s and %s arguments order looks reversed", firstStr, secondStr))
		}

		return true
	})

	return warnings
}

func isStringLiteral(expr ast.Expr) bool {
	lit, ok := expr.(*ast.BasicLit)
	return ok && lit.Kind == token.STRING
}

func isSimpleVar(expr ast.Expr) bool {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name != "nil" && e.Name != "true" && e.Name != "false"
	case *ast.SelectorExpr:
		return true
	}
	return false
}

// assignOp: Detects assignments that can use assignment operators
func checkAssignOp(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	type opWarning struct {
		pos  token.Pos
		text string
	}
	opMap := make(map[string][]opWarning) // keyed by operator string

	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN {
			return true
		}
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}

		lhs := assign.Lhs[0]
		rhs := assign.Rhs[0]

		// Check if RHS is: lhs op something
		bin, ok := rhs.(*ast.BinaryExpr)
		if !ok {
			return true
		}

		if !exprEqual(lhs, bin.X) {
			return true
		}

		op := bin.Op
		var suggestion string
		var opStr string

		// Check for x = x + 1 -> x++ and x = x - 1 -> x--
		if op == token.ADD && isIntLit(bin.Y, "1") {
			suggestion = fmt.Sprintf("%s++", formatNode(lhs))
			opStr = "+"
		} else if op == token.SUB && isIntLit(bin.Y, "1") {
			suggestion = fmt.Sprintf("%s--", formatNode(lhs))
			opStr = "-"
		} else {
			switch op {
			case token.ADD:
				suggestion = fmt.Sprintf("%s += %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "+"
			case token.SUB:
				suggestion = fmt.Sprintf("%s -= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "-"
			case token.MUL:
				suggestion = fmt.Sprintf("%s *= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "*"
			case token.QUO:
				suggestion = fmt.Sprintf("%s /= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "/"
			case token.REM:
				suggestion = fmt.Sprintf("%s %%= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "%"
			case token.AND:
				suggestion = fmt.Sprintf("%s &= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "&"
			case token.OR:
				suggestion = fmt.Sprintf("%s |= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "|"
			case token.XOR:
				suggestion = fmt.Sprintf("%s ^= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "^"
			case token.SHL:
				suggestion = fmt.Sprintf("%s <<= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "<<"
			case token.SHR:
				suggestion = fmt.Sprintf("%s >>= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = ">>"
			case token.AND_NOT:
				suggestion = fmt.Sprintf("%s &^= %s", formatNode(lhs), formatNode(bin.Y))
				opStr = "&^"
			default:
				return true
			}
		}

		origAssign := formatNode(assign)
		text := fmt.Sprintf("replace `%s` with `%s`", origAssign, suggestion)
		opMap[opStr] = append(opMap[opStr], opWarning{assign.Pos(), text})
		return true
	})

	// Sort operator keys and output in sorted order
	keys := make([]string, 0, len(opMap))
	for k := range opMap {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var warnings []Warning
	for _, k := range keys {
		for _, w := range opMap[k] {
			warnings = append(warnings, Warning{Pos: w.pos, Text: w.text})
		}
	}

	return warnings
}

// badCall: Detects suspicious function calls
func checkBadCall(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg {
			return true
		}

		switch pkg {
		case "strings":
			switch name {
			case "Replace", "SplitN", "SplitAfterN":
				if len(call.Args) >= 4 {
					// Last arg should be -1 for Replace/SplitN/SplitAfterN when 0 is passed
					lastArg := call.Args[len(call.Args)-1]
					if isIntLit(lastArg, "0") {
						warnings = append(warnings, warn(lastArg.Pos(),
							"suspicious arg 0, probably meant -1"))
					}
				}
			}
		case "bytes":
			switch name {
			case "Replace", "SplitN", "SplitAfterN":
				if len(call.Args) >= 4 {
					lastArg := call.Args[len(call.Args)-1]
					if isIntLit(lastArg, "0") {
						warnings = append(warnings, warn(lastArg.Pos(),
							"suspicious arg 0, probably meant -1"))
					}
				}
			}
		}

		return true
	})

	return warnings
}

// badCond: Detects suspicious condition expressions
func checkBadCond(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		forStmt, ok := n.(*ast.ForStmt)
		if !ok || forStmt.Init == nil || forStmt.Cond == nil || forStmt.Post == nil {
			return true
		}

		// Check: for i := 0; i > n; i++
		initAssign, ok := forStmt.Init.(*ast.AssignStmt)
		if !ok || initAssign.Tok != token.DEFINE || len(initAssign.Lhs) != 1 || len(initAssign.Rhs) != 1 {
			return true
		}

		// Init should assign 0
		if !isIntLit(initAssign.Rhs[0], "0") {
			return true
		}

		cond, ok := forStmt.Cond.(*ast.BinaryExpr)
		if !ok {
			return true
		}

		// Cond should be: i > n (where i is initialized to 0)
		if cond.Op != token.GTR {
			return true
		}

		// Check post is i++
		incDecStmt, ok := forStmt.Post.(*ast.IncDecStmt)
		if !ok || incDecStmt.Tok != token.INC {
			return true
		}

		// i from init
		initVar := initAssign.Lhs[0]
		// i from cond.X
		condVar := cond.X
		// i from post
		postVar := incDecStmt.X

		if !exprEqual(initVar, condVar) || !exprEqual(initVar, postVar) {
			return true
		}

		warnings = append(warnings, warn(forStmt.Pos(),
			"suspicious condition for loop with body `%s`",
			formatNode(forStmt.Cond)))
		return true
	})

	return warnings
}

// badLock: Detects suspicious mutex lock/unlock operations
func checkBadLock(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		exprStmt, ok := n.(*ast.ExprStmt)
		if !ok {
			return true
		}

		call, ok := exprStmt.X.(*ast.CallExpr)
		if !ok {
			return true
		}

		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Lock" {
			return true
		}

		// We found x.Lock() - check if it's in the same statement list as x.Unlock()
		// This is simplified; the real checker is more sophisticated
		_ = sel

		return true
	})

	return warnings
}

// badRegexp: Detects suspicious regexp patterns
func checkBadRegexp(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}

		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg {
			return true
		}
		if pkg != "regexp" {
			return true
		}
		if name != "Compile" && name != "MustCompile" && name != "CompilePOSIX" && name != "MustCompilePOSIX" && name != "Match" && name != "MatchString" && name != "MatchReader" {
			return true
		}

		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}

		// Extract string value
		pattern := strings.Trim(lit.Value, "`\"")

		// Check for redundant character class (e.g., [a] instead of a)
		// or common mistakes
		_ = pattern

		return true
	})

	return warnings
}

// badSorting: Detects bad usage of sort package
func checkBadSorting(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}

		for _, rhs := range assign.Rhs {
			call, ok := rhs.(*ast.CallExpr)
			if !ok {
				continue
			}

			pkg, name, hasPkg := getCallPkgFunc(call)
			if !hasPkg || pkg != "sort" {
				continue
			}

			switch name {
			case "StringSlice", "IntSlice", "Float64Slice":
				warnings = append(warnings, warn(call.Pos(),
					"use sort.Strings/Ints/Float64s instead of converting to sort.%s", name))
			}
		}

		return true
	})

	return warnings
}

// badSyncOnceFunc: Detects bad usage of sync.OnceFunc
func checkBadSyncOnceFunc(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		// Check if this is sync.OnceFunc(f)() pattern (called immediately)
		innerCall, ok := call.Fun.(*ast.CallExpr)
		if !ok {
			return true
		}

		if isSelector(innerCall.Fun, "sync", "OnceFunc") {
			warnings = append(warnings, warn(call.Pos(),
				"sync.OnceFunc result is called immediately, which defeats its purpose"))
		}

		return true
	})

	return warnings
}

// boolExprSimplify: Detects bool expressions that can be simplified
func checkBoolExprSimplify(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		unary, ok := n.(*ast.UnaryExpr)
		if !ok || unary.Op != token.NOT {
			return true
		}

		inner, ok := unary.X.(*ast.BinaryExpr)
		if !ok {
			return true
		}

		switch inner.Op {
		case token.GTR: // !(x > y) -> x <= y
			warnings = append(warnings, warn(unary.Pos(),
				"can simplify `!(%s %s %s)` to `%s <= %s`",
				formatNode(inner.X), inner.Op, formatNode(inner.Y),
				formatNode(inner.X), formatNode(inner.Y)))
		case token.LSS: // !(x < y) -> x >= y
			warnings = append(warnings, warn(unary.Pos(),
				"can simplify `!(%s %s %s)` to `%s >= %s`",
				formatNode(inner.X), inner.Op, formatNode(inner.Y),
				formatNode(inner.X), formatNode(inner.Y)))
		case token.GEQ: // !(x >= y) -> x < y
			warnings = append(warnings, warn(unary.Pos(),
				"can simplify `!(%s %s %s)` to `%s < %s`",
				formatNode(inner.X), inner.Op, formatNode(inner.Y),
				formatNode(inner.X), formatNode(inner.Y)))
		case token.LEQ: // !(x <= y) -> x > y
			warnings = append(warnings, warn(unary.Pos(),
				"can simplify `!(%s %s %s)` to `%s > %s`",
				formatNode(inner.X), inner.Op, formatNode(inner.Y),
				formatNode(inner.X), formatNode(inner.Y)))
		}

		return true
	})

	return warnings
}

var builtinIdents = map[string]bool{
	"append": true, "cap": true, "close": true, "complex": true,
	"copy": true, "delete": true, "imag": true, "len": true,
	"make": true, "new": true, "panic": true, "print": true,
	"println": true, "real": true, "recover": true,
	"bool": true, "byte": true, "complex64": true, "complex128": true,
	"error": true, "float32": true, "float64": true,
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"rune": true, "string": true,
	"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"uintptr": true,
	"true": true, "false": true, "iota": true, "nil": true,
}

// builtinShadow: Detects when predeclared identifiers are shadowed
func checkBuiltinShadow(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.AssignStmt:
			if x.Tok != token.DEFINE && x.Tok != token.ASSIGN {
				return true
			}
			for _, lhs := range x.Lhs {
				if id, ok := lhs.(*ast.Ident); ok {
					if builtinIdents[id.Name] {
						warnings = append(warnings, warn(id.Pos(),
							"shadowing of predeclared identifier: %s", id.Name))
					}
				}
			}
		case *ast.ValueSpec:
			for _, name := range x.Names {
				if builtinIdents[name.Name] {
					warnings = append(warnings, warn(name.Pos(),
						"shadowing of predeclared identifier: %s", name.Name))
				}
			}
		}
		return true
	})

	return warnings
}

// builtinShadowDecl: Detects top-level declarations that shadow predeclared identifiers
func checkBuiltinShadowDecl(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Recv == nil && builtinIdents[d.Name.Name] {
				warnings = append(warnings, warn(d.Name.Pos(),
					"shadowing of predeclared identifier: %s", d.Name.Name))
			}
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					if builtinIdents[s.Name.Name] {
						warnings = append(warnings, warn(s.Name.Pos(),
							"shadowing of predeclared identifier: %s", s.Name.Name))
					}
				case *ast.ValueSpec:
					for _, name := range s.Names {
						if builtinIdents[name.Name] {
							warnings = append(warnings, warn(name.Pos(),
								"shadowing of predeclared identifier: %s", name.Name))
						}
					}
				}
			}
		}
	}

	return warnings
}

// captLocal: Detects capitalized local variable names
func checkCaptLocal(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	p, _ := params.(*checkParams)
	paramsOnly := true
	if p != nil {
		paramsOnly = p.CaptLocalParamsOnly
	}

	isCapitalized := func(name string) bool {
		if len(name) == 0 {
			return false
		}
		return unicode.IsUpper(rune(name[0]))
	}

	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if fn.Type.Params != nil {
			for _, field := range fn.Type.Params.List {
				for _, name := range field.Names {
					if isCapitalized(name.Name) {
						warnings = append(warnings, warn(name.Pos(),
							"consider `%s` name instead of `%s`",
							strings.ToLower(name.Name[:1])+name.Name[1:],
							name.Name))
					}
				}
			}
		}

		if fn.Type.Results != nil {
			for _, field := range fn.Type.Results.List {
				for _, name := range field.Names {
					if isCapitalized(name.Name) {
						warnings = append(warnings, warn(name.Pos(),
							"consider `%s` name instead of `%s`",
							strings.ToLower(name.Name[:1])+name.Name[1:],
							name.Name))
					}
				}
			}
		}

		if !paramsOnly && fn.Body != nil {
			ast.Inspect(fn.Body, func(n2 ast.Node) bool {
				assign, ok := n2.(*ast.AssignStmt)
				if !ok || assign.Tok != token.DEFINE {
					return true
				}
				for _, lhs := range assign.Lhs {
					if id, ok := lhs.(*ast.Ident); ok && isCapitalized(id.Name) && id.Name != "_" {
						warnings = append(warnings, warn(id.Pos(),
							"consider `%s` name instead of `%s`",
							strings.ToLower(id.Name[:1])+id.Name[1:],
							id.Name))
					}
				}
				return true
			})
		}

		return true
	})

	return warnings
}

// caseOrder: Detects wrong order in type switch cases
func checkCaseOrder(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	if ctx.TypesInfo == nil {
		return nil
	}

	ast.Inspect(f, func(n ast.Node) bool {
		sw, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}

		body := sw.Body
		var cases []ast.Expr
		var casePos []token.Pos

		for _, stmt := range body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok || cc.List == nil {
				continue
			}
			for _, t := range cc.List {
				cases = append(cases, t)
				casePos = append(casePos, cc.Pos())
			}
		}

		// Check if any interface case should come after a concrete type case  
		// that implements it
		for i := 0; i < len(cases); i++ {
			for j := i + 1; j < len(cases); j++ {
				ti := ctx.TypesInfo.Types[cases[i]]
				tj := ctx.TypesInfo.Types[cases[j]]

				if !ti.IsType() || !tj.IsType() {
					continue
				}

				iface, ok := ti.Type.Underlying().(*types.Interface)
				if !ok {
					continue
				}

				// cases[i] is an interface, cases[j] might implement it
				if types.Implements(tj.Type, iface) {
					warnings = append(warnings, warn(casePos[j],
						"case %s must go before the %s case",
						formatNode(cases[j]), formatNode(cases[i])))
				}
			}
		}

		return true
	})

	return warnings
}

// codegenComment: Detects malformed code generated comments
func checkCodegenComment(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	// The standard format is: "// Code generated ... DO NOT EDIT."
	// Check file-level comments for malformed codegen comments
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			text := c.Text
			lower := strings.ToLower(text)

			// Check for lines that mention "generated" or "do not edit" but not in standard format
			if (strings.Contains(lower, "generated") || strings.Contains(lower, "do not edit")) &&
				!strings.Contains(text, "Code generated") {
				// This might be a malformed codegen comment
				if strings.Contains(lower, "autom") || strings.Contains(lower, "generated by") ||
					strings.Contains(lower, "do not edit") || strings.Contains(lower, "do not modify") {
					warnings = append(warnings, warn(c.Pos(),
						"use standard 'Code generated ... DO NOT EDIT.' comment format"))
				}
			}
		}
	}

	return warnings
}

// commentFormatting: Detects non-idiomatic comment formatting
func checkCommentFormatting(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	for _, cg := range f.Comments {
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			if strings.HasPrefix(c.Text, "///") {
				continue
			}

			text := c.Text[2:] // Remove "//"
			if len(text) == 0 {
				continue // Empty comment is fine
			}

			// Special cases that are OK without space:
			// - //go:xxx directives
			// - //+build directives
			// - //nolint comments
			// - //go:generate
			if strings.HasPrefix(text, "go:") ||
				strings.HasPrefix(text, "+build") ||
				strings.HasPrefix(text, "nolint") ||
				strings.HasPrefix(text, "NOSONAR") {
				continue
			}

			// URL-like patterns are OK
			if strings.HasPrefix(text, "http://") || strings.HasPrefix(text, "https://") {
				continue
			}

			// Check if first char is not space or not a special char
			if len(text) > 0 && text[0] != ' ' && text[0] != '\t' {
				warnings = append(warnings, warn(c.Pos(),
					"put a space between `//` and comment text"))
				break // Only warn once per comment group
			}
		}
	}

	return warnings
}

// commentedOutCode: Detects commented-out code in function bodies
func checkCommentedOutCode(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	p, _ := params.(*checkParams)
	minLength := 15
	if p != nil {
		minLength = p.CommentedOutCodeMinLength
	}

	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}

		// Find comments within the function body
		bodyStart := fn.Body.Pos()
		bodyEnd := fn.Body.End()

		for _, cg := range f.Comments {
			for _, c := range cg.List {
				if c.Pos() < bodyStart || c.Pos() >= bodyEnd {
					continue
				}

				text := c.Text
				if !strings.HasPrefix(text, "//") {
					continue
				}

				commentText := strings.TrimPrefix(text, "//")
				commentText = strings.TrimSpace(commentText)

				if len(commentText) < minLength {
					continue
				}

				// Try to parse as code
				if looksLikeCode(commentText) {
					warnings = append(warnings, warn(c.Pos(),
						"may want to delete commented-out code"))
				}
			}
		}

		return true
	})

	return warnings
}

func looksLikeCode(text string) bool {
	// Simple heuristic: looks like a function call, assignment, etc.
	if strings.Contains(text, "(") && strings.Contains(text, ")") {
		return true
	}
	if strings.Contains(text, ":=") || strings.Contains(text, " = ") {
		return true
	}
	return false
}

// commentedOutImport: Detects commented-out imports
func checkCommentedOutImport(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	for _, decl := range f.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		// Find comments inside the import block
		importStart := genDecl.Pos()
		importEnd := genDecl.End()

		for _, cg := range f.Comments {
			for _, c := range cg.List {
				if c.Pos() <= importStart || c.Pos() >= importEnd {
					continue
				}

				text := strings.TrimPrefix(c.Text, "//")
				text = strings.TrimSpace(text)

				// Check if it looks like an import path
				if strings.HasPrefix(text, `"`) && strings.HasSuffix(text, `"`) {
					warnings = append(warnings, warn(c.Pos(),
						"import %s is commented out", text))
				}
			}
		}
	}

	return warnings
}

// defaultCaseOrder: Detects wrong position of default case in switch
func checkDefaultCaseOrder(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}

		cases := sw.Body.List
		if len(cases) <= 1 {
			return true
		}

		// Find position of default case
		defaultPos := -1
		for i, stmt := range cases {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			if cc.List == nil { // default case has nil list
				defaultPos = i
			}
		}

		// Default should be at position 0 or len-1
		if defaultPos > 0 && defaultPos < len(cases)-1 {
			warnings = append(warnings, warn(cases[defaultPos].Pos(),
				"default case should be first or last in switch statement"))
		}

		return true
	})

	return warnings
}

// deferInLoop: Detects defers inside loops
func checkDeferInLoop(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.ForStmt, *ast.RangeStmt:
			// Check if there's a defer inside this loop
			ast.Inspect(x.(ast.Node), func(n2 ast.Node) bool {
				if n2 == x {
					return true
				}
				// Don't go into nested function literals
				if _, ok := n2.(*ast.FuncLit); ok {
					return false
				}
				if deferStmt, ok := n2.(*ast.DeferStmt); ok {
					warnings = append(warnings, warn(deferStmt.Pos(),
						"defer in a loop; consider moving it outside or use a closure"))
				}
				return true
			})
		}
		return true
	})

	return warnings
}

// deferUnlambda: Detects deferred function literals that can be simplified
func checkDeferUnlambda(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		deferStmt, ok := n.(*ast.DeferStmt)
		if !ok {
			return true
		}

		call, ok := deferStmt.Call.Fun.(*ast.FuncLit)
		if !ok {
			return true
		}

		// Check if the function literal just calls another function
		if len(call.Type.Params.List) != 0 {
			return true
		}

		body := call.Body
		if len(body.List) != 1 {
			return true
		}

		exprStmt, ok := body.List[0].(*ast.ExprStmt)
		if !ok {
			return true
		}

		innerCall, ok := exprStmt.X.(*ast.CallExpr)
		if !ok {
			return true
		}

		// Check if inner call has no arguments (so we can simplify)
		if len(innerCall.Args) == 0 && len(deferStmt.Call.Args) == 0 {
			warnings = append(warnings, warn(deferStmt.Pos(),
				"can remove lambda wrapper around `%s`", formatNode(innerCall.Fun)))
		}

		return true
	})

	return warnings
}

// deprecatedComment: Detects malformed deprecated comments
func checkDeprecatedComment(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		var commentGroups []*ast.CommentGroup
		var pos token.Pos

		switch x := n.(type) {
		case *ast.FuncDecl:
			commentGroups = []*ast.CommentGroup{x.Doc}
			pos = x.Pos()
		case *ast.TypeSpec:
			// TypeSpec gets doc from parent GenDecl
			return true
		case *ast.ValueSpec:
			return true
		}

		for _, cg := range commentGroups {
			if cg == nil {
				continue
			}
			for _, c := range cg.List {
				text := c.Text[2:] // Remove "//"
				text = strings.TrimSpace(text)
				// Check if it starts with "deprecated" but not "Deprecated:"
				lower := strings.ToLower(text)
				if strings.HasPrefix(lower, "deprecated") && !strings.HasPrefix(text, "Deprecated:") {
					warnings = append(warnings, warn(pos,
						"use 'Deprecated: ...' format for deprecated comment"))
				}
			}
		}

		return true
	})

	return warnings
}

// docStub: Detects doc comment stubs
func checkDocStub(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Doc == nil {
			return true
		}

		if !fn.Name.IsExported() {
			return true
		}

		// Check if doc is just "<funcname> ..."
		doc := fn.Doc.Text()
		doc = strings.TrimSpace(doc)
		if strings.HasPrefix(doc, fn.Name.Name+" ...") ||
			(doc == fn.Name.Name+" ...") {
			warnings = append(warnings, warn(fn.Pos(),
				"stub doc comment"))
		}

		return true
	})

	return warnings
}

// dupArg: Detects suspicious duplicate function arguments
func checkDupArg(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	// Functions that should not have duplicate args
	checkFuncs := map[string]bool{
		"copy":    true,
		"append":  true,
	}

	// Package functions with duplicate arg warnings
	pkgFuncs := map[string][]int{
		"strings.Compare": {0, 1},
		"strings.Contains": {0, 1},
		"strings.EqualFold": {0, 1},
		"bytes.Compare": {0, 1},
		"bytes.Contains": {0, 1},
		"bytes.Equal": {0, 1},
	}

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		if id, ok := call.Fun.(*ast.Ident); ok && checkFuncs[id.Name] {
			if len(call.Args) == 2 && exprEqual(call.Args[0], call.Args[1]) {
				warnings = append(warnings, warn(call.Pos(),
					"suspicious duplicated args in %s(%s, %s)",
					id.Name, formatNode(call.Args[0]), formatNode(call.Args[1])))
			}
		}

		pkg, name, hasPkg := getCallPkgFunc(call)
		if hasPkg {
			key := pkg + "." + name
			if indices, ok := pkgFuncs[key]; ok {
				if len(call.Args) > indices[1] {
					if exprEqual(call.Args[indices[0]], call.Args[indices[1]]) {
						warnings = append(warnings, warn(call.Pos(),
							"suspicious duplicated args in %s(%s, %s)",
							formatNode(call.Fun),
							formatNode(call.Args[indices[0]]),
							formatNode(call.Args[indices[1]])))
					}
				}
			}
		}

		return true
	})

	return warnings
}

// dupBranchBody: Detects duplicate branch bodies
func checkDupBranchBody(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}

		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}

		if blockEqual(ifStmt.Body, elseBlock) {
			warnings = append(warnings, warn(ifStmt.Pos(),
				"both branches are identical"))
		}

		return true
	})

	return warnings
}

// dupCase: Detects duplicate case clauses in switch
func checkDupCase(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}

		seen := make(map[string]bool)
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, expr := range cc.List {
				key := formatNode(expr)
				if seen[key] {
					warnings = append(warnings, warn(expr.Pos(),
						"duplicate case %s in switch", key))
				}
				seen[key] = true
			}
		}

		return true
	})

	return warnings
}

// dupImport: Detects multiple imports of the same package
func checkDupImport(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	paths := make(map[string]string) // path -> first alias

	for _, importSpec := range f.Imports {
		path := strings.Trim(importSpec.Path.Value, `"`)

		alias := ""
		if importSpec.Name != nil {
			alias = importSpec.Name.Name
		}

		if firstAlias, seen := paths[path]; seen {
			if firstAlias != alias {
				warnings = append(warnings, warn(importSpec.Pos(),
					"package %q already imported as %q", path, firstAlias))
			}
		} else {
			paths[path] = alias
		}
	}

	return warnings
}

// dupOption: Detects duplicate options in variadic calls (simplified)
func checkDupOption(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	// This is a complex checker that requires type info
	return nil
}

// dupSubExpr: Detects suspicious duplicate sub-expressions
func checkDupSubExpr(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}

		// Skip logical AND/OR (common patterns like x != nil && x.foo)
		if bin.Op == token.LAND || bin.Op == token.LOR {
			return true
		}

		if exprEqual(bin.X, bin.Y) {
			switch bin.Op {
			case token.LSS, token.GTR, token.LEQ, token.GEQ, token.EQL, token.NEQ,
				token.SUB, token.QUO, token.REM:
				warnings = append(warnings, warn(bin.Pos(),
					"suspicious identical LHS and RHS for `%s` operator", bin.Op))
			}
		}

		return true
	})

	return warnings
}

// dynamicFmtString: Detects dynamic format strings in fmt functions
func checkDynamicFmtString(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	fmtFuncs := map[string]bool{
		"Errorf": true, "Sprintf": true, "Fprintf": true, "Printf": true,
		"Fatalf": true, "Panicf": true,
	}

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg || pkg != "fmt" || !fmtFuncs[name] {
			return true
		}

		// Check if format string is a variable (not a literal)
		fmtArgIdx := 0
		if name == "Fprintf" || name == "Fscanf" {
			fmtArgIdx = 1
		}

		if len(call.Args) > fmtArgIdx {
			fmtArg := call.Args[fmtArgIdx]
			if _, ok := fmtArg.(*ast.BasicLit); !ok {
				// Format string is not a literal
				if len(call.Args) == fmtArgIdx+1 {
					// Only one argument (no additional format args)
					warnings = append(warnings, warn(call.Pos(),
						"use fmt.Sprint instead of fmt.Sprintf when using just one variable"))
				}
			}
		}

		return true
	})

	return warnings
}

// checkParams holds parameter values for checkers
type checkParams struct {
	CaptLocalParamsOnly        bool
	CommentedOutCodeMinLength  int
	ElseifSkipBalanced         bool
	HugeParamSizeThreshold     int
	IfElseChainMinThreshold    int
	NestingReduceBodyWidth     int
	RangeExprCopySizeThreshold int
