func checkRegexpMust(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for _, rhs := range assign.Rhs {
			call, ok := rhs.(*ast.CallExpr)
			if !ok {
				continue
			}
			pkg, name, hasPkg := getCallPkgFunc(call)
			if !hasPkg || pkg != "regexp" {
				continue
			}
			if name != "Compile" && name != "CompilePOSIX" {
				continue
			}
			if len(call.Args) < 1 {
				continue
			}
			if _, ok := call.Args[0].(*ast.BasicLit); ok {
				// Pattern is a constant - can use Must variant
				mustName := "MustCompile"
				if name == "CompilePOSIX" {
					mustName = "MustCompilePOSIX"
				}
				warnings = append(warnings, warn(call.Pos(),
					"for const patterns like %s, use regexp.%s",
					formatNode(call.Args[0]), mustName))
			}
		}
		return true
	})
	return warnings
}

func checkRegexpPattern(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg || pkg != "regexp" {
			return true
		}
		if name != "Compile" && name != "MustCompile" {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		pattern := strings.Trim(lit.Value, "`\"")
		// Check for unescaped dots in patterns that look like domain names
		if strings.Contains(pattern, ".com") || strings.Contains(pattern, ".org") {
			if !strings.Contains(pattern, `\.`) {
				warnings = append(warnings, warn(call.Pos(),
					"pattern may have unescaped dots"))
			}
		}
		return true
	})
	return warnings
}

