		nonDefaultCases := 0
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			if cc.List != nil {
				nonDefaultCases++
			}
		}
		if nonDefaultCases == 1 && len(sw.Body.List) == 1 {
			warnings = append(warnings, warn(sw.Pos(),
				"should rewrite switch statement to if statement"))
		}
		return true
	})
	return warnings
}

