		if len(call.Args) < 1 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		val := strings.ToUpper(strings.Trim(lit.Value, `"`))
		if strings.HasPrefix(val, "UPDATE") || strings.HasPrefix(val, "INSERT") ||
			strings.HasPrefix(val, "DELETE") {
			warnings = append(warnings, warn(call.Pos(),
				"use Exec instead of Query for non-SELECT statements"))
