func checkTooManyResultsChecker(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	p, _ := params.(*checkParams)
	maxResults := 5
	if p != nil {
		maxResults = p.TooManyResultsMax
	}
	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type.Results == nil {
			return true
		}
		count := 0
		for _, r := range fn.Type.Results.List {
			if len(r.Names) == 0 {
				count++
			} else {
				count += len(r.Names)
			}
		}
		if count > maxResults {
			warnings = append(warnings, warn(fn.Pos(),
				"function has %d results, consider using a struct", count))
		}
		return true
	})
	return warnings
}

