func checkTypeSwitchVar(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		sw, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		assign, ok := sw.Assign.(*ast.ExprStmt)
		if !ok {
			return true
		}
		ta, ok := assign.X.(*ast.TypeAssertExpr)
		if !ok {
			return true
		}
		switchVar := formatNode(ta.X)
		count := 0
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok || cc.List == nil {
				continue
			}
			// Check if body uses type assertion on switchVar
			for _, bodyStmt := range cc.Body {
				ast.Inspect(bodyStmt, func(n2 ast.Node) bool {
					ta2, ok := n2.(*ast.TypeAssertExpr)
					if !ok {
						return true
					}
					if formatNode(ta2.X) == switchVar {
						count++
					}
					return true
				})
			}
		}
		if count > 0 {
			warnings = append(warnings, warn(sw.Pos(),
				"%d case can benefit from type switch with assignment", count))
		}
		return true
	})
	return warnings
}

