func checkUnderef(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.SelectorExpr:
			paren, ok := x.X.(*ast.ParenExpr)
			if !ok {
				return true
			}
			star, ok := paren.X.(*ast.UnaryExpr)
			if !ok || star.Op != token.MUL {
				return true
			}
			warnings = append(warnings, warn(x.Pos(),
				"could simplify (*%s).%s to %s.%s",
				formatNode(star.X), x.Sel.Name,
				formatNode(star.X), x.Sel.Name))
		case *ast.IndexExpr:
			paren, ok := x.X.(*ast.ParenExpr)
			if !ok {
				return true
			}
			star, ok := paren.X.(*ast.UnaryExpr)
			if !ok || star.Op != token.MUL {
				return true
			}
			warnings = append(warnings, warn(x.Pos(),
				"could simplify (*%s)[%s] to %s[%s]",
				formatNode(star.X), formatNode(x.Index),
				formatNode(star.X), formatNode(x.Index)))
		}
		return true
	})
	return warnings
}

