func checkUnnecessaryDefer(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		if fn.Body == nil || len(fn.Body.List) == 0 {
			return true
		}
		// Check if the last statement is a defer
		last := fn.Body.List[len(fn.Body.List)-1]
		if _, ok := last.(*ast.DeferStmt); ok && len(fn.Body.List) == 1 {
			warnings = append(warnings, warn(last.Pos(),
