func checkEmptyStringTest(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fn, ok := call.Fun.(*ast.Ident)
		if !ok || fn.Name != "len" || len(call.Args) != 1 {
			return true
		}
		arg := call.Args[0]
		rhs := bin.Y
		switch bin.Op {
		case token.EQL:
			if isIntLit(rhs, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) == 0` with `%s == \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		case token.NEQ:
			if isIntLit(rhs, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) != 0` with `%s != \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		case token.GTR:
			if isIntLit(rhs, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) > 0` with `%s != \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		case token.GEQ:
			if isIntLit(rhs, "1") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) >= 1` with `%s != \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		case token.LSS:
			if isIntLit(rhs, "1") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) < 1` with `%s == \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		case token.LEQ:
			if isIntLit(rhs, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace `len(%s) <= 0` with `%s == \"\"`",
					formatNode(arg), formatNode(arg)))
			}
		}
		return true
	})
	return warnings
}

func checkEqualFold(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}
		call1, ok1 := bin.X.(*ast.CallExpr)
		call2, ok2 := bin.Y.(*ast.CallExpr)
		if !ok1 || !ok2 {
			return true
		}
		isToLower := func(c *ast.CallExpr) bool {
			return isSelector(c.Fun, "strings", "ToLower") && len(c.Args) == 1
		}
		isToUpper := func(c *ast.CallExpr) bool {
			return isSelector(c.Fun, "strings", "ToUpper") && len(c.Args) == 1
		}
		if (isToLower(call1) && isToLower(call2)) || (isToUpper(call1) && isToUpper(call2)) {
			warnings = append(warnings, warn(bin.Pos(),
				"can replace with strings.EqualFold(%s, %s)",
				formatNode(call1.Args[0]), formatNode(call2.Args[0])))
		}
		return true
	})
	return warnings
