func checkExitAfterDefer(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	exitFuncs := map[string]bool{
		"log.Fatal": true, "log.Fatalf": true, "log.Fatalln": true,
		"os.Exit": true,
	}
	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		hasDefer := false
		ast.Inspect(fn.Body, func(n2 ast.Node) bool {
			if _, ok := n2.(*ast.DeferStmt); ok {
				hasDefer = true
			}
			return true
		})
		if !hasDefer {
			return true
		}
		ast.Inspect(fn.Body, func(n2 ast.Node) bool {
			call, ok := n2.(*ast.CallExpr)
			if !ok {
				return true
			}
			pkg, name, hasPkg := getCallPkgFunc(call)
			if !hasPkg {
				return true
			}
			key := pkg + "." + name
			if exitFuncs[key] {
				warnings = append(warnings, warn(call.Pos(),
					"os.Exit or log.Fatal called in a function with deferred calls"))
			}
			return true
		})
		return true
	})
	return warnings
}

func checkExposedSyncMutex(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		typeSpec, ok := n.(*ast.TypeSpec)
		if !ok {
			return true
		}
		structType, ok := typeSpec.Type.(*ast.StructType)
		if !ok {
			return true
		}
		for _, field := range structType.Fields.List {
			if len(field.Names) != 0 {
				continue
			}
			// Anonymous field
			sel, ok := field.Type.(*ast.SelectorExpr)
			if !ok {
				continue
			}
			if isIdent(sel.X, "sync") && (sel.Sel.Name == "Mutex" || sel.Sel.Name == "RWMutex") {
				warnings = append(warnings, warn(field.Pos(),
					"embedded sync.%s exposes its methods", sel.Sel.Name))
			}
		}
		return true
	})
	return warnings
}

func checkExternalErrorReassign(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN {
			return true
		}
		for _, lhs := range assign.Lhs {
			sel, ok := lhs.(*ast.SelectorExpr)
			if !ok {
				continue
			}
			id, ok := sel.X.(*ast.Ident)
			if !ok {
				continue
			}
			if id.Name != id.Name {
				continue
			}
			// Check if it's a well-known error variable from another package
			if sel.Sel.Name == "EOF" || sel.Sel.Name == "ErrClosed" {
				warnings = append(warnings, warn(assign.Pos(),
					"suspicious reassignment of error variable from external package"))
			}
		}
		return true
	})
	return warnings
