		}
		count := 0
		for _, r := range fn.Type.Results.List {
			if len(r.Names) == 0 {
				count++
			} else {
				count += len(r.Names)
			}
		}
		if count > maxResults {
			warnings = append(warnings, warn(fn.Pos(),
				"function has %d results, consider using a struct", count))
		}
		return true
	})
	return warnings
}

