			if strings.HasSuffix(val, "/") || strings.HasSuffix(val, "\\") {
				warnings = append(warnings, warn(arg.Pos(),
					"filepath.Join argument has a trailing slash"))
				break
			}
		}
		return true
	})
	return warnings
}

func checkFlagDeref(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	flagFuncs := map[string]bool{
		"Bool": true, "Int": true, "Int64": true, "Float64": true,
		"String": true, "Duration": true, "Uint": true, "Uint64": true,
	}
	ast.Inspect(f, func(n ast.Node) bool {
		unary, ok := n.(*ast.UnaryExpr)
		if !ok || unary.Op != token.MUL {
			return true
		}
		call, ok := unary.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg || pkg != "flag" || !flagFuncs[name] {
			return true
		}
		warnings = append(warnings, warn(unary.Pos(),
			"immediate deref of flag.%s is fragile; use flag.%sVar instead", name, name))
		return true
	})
	return warnings
}

func checkFlagName(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	flagFuncs := map[string]bool{
		"Bool": true, "Int": true, "Int64": true, "Float64": true,
		"String": true, "Duration": true, "Uint": true, "Uint64": true,
		"BoolVar": true, "IntVar": true, "Int64Var": true, "Float64Var": true,
		"StringVar": true, "DurationVar": true, "UintVar": true, "Uint64Var": true,
	}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg || pkg != "flag" || !flagFuncs[name] {
			return true
		}
		nameArgIdx := 0
		if strings.HasSuffix(name, "Var") {
			nameArgIdx = 1
		}
		if len(call.Args) <= nameArgIdx {
			return true
		}
		arg := call.Args[nameArgIdx]
		lit, ok := arg.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		val := strings.Trim(lit.Value, `"`)
		if strings.HasPrefix(val, " ") || strings.HasSuffix(val, " ") ||
			strings.HasPrefix(val, "-") || strings.HasPrefix(val, "=") {
			warnings = append(warnings, warn(arg.Pos(),
				"suspicious flag name %q", val))
		}
		return true
	})
	return warnings
}

func checkHexLiteral(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.INT {
			return true
		}
		val := lit.Value
		if strings.HasPrefix(val, "0X") {
			warnings = append(warnings, warn(lit.Pos(),
				"prefer 0x prefix over 0X for hex literals"))
		} else if strings.HasPrefix(val, "0x") {
			// Check for mixed case
			hex := val[2:]
			hasLower := false
			hasUpper := false
			for _, c := range hex {
				if c >= 'a' && c <= 'f' {
					hasLower = true
				}
				if c >= 'A' && c <= 'F' {
					hasUpper = true
				}
			}
			if hasLower && hasUpper {
				warnings = append(warnings, warn(lit.Pos(),
					"hex literal %s has mixed case digits", val))
			}
		}
		return true
	})
	return warnings
}

