func checkSloppyLen(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fn, ok := call.Fun.(*ast.Ident)
		if !ok || fn.Name != "len" || len(call.Args) != 1 {
			return true
		}
		switch bin.Op {
		case token.GEQ:
			if isIntLit(bin.Y, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"len(%s) >= 0 is always true", formatNode(call.Args[0])))
			}
		case token.LSS:
			if isIntLit(bin.Y, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"len(%s) < 0 is always false", formatNode(call.Args[0])))
			}
		case token.LEQ:
			if isIntLit(bin.Y, "0") {
				warnings = append(warnings, warn(bin.Pos(),
					"replace len(%s) <= 0 with len(%s) == 0",
					formatNode(call.Args[0]), formatNode(call.Args[0])))
			}
		case token.NEQ:
			if isIntLit(bin.Y, "0") {
				// This is fine
			}
		}
		return true
	})
	return warnings
}

