func checkSloppyTypeAssert(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	if ctx.TypesInfo == nil {
		return nil
	}
	ast.Inspect(f, func(n ast.Node) bool {
		ta, ok := n.(*ast.TypeAssertExpr)
		if !ok || ta.Type == nil {
			return true
		}
		// Check if the type assertion is to the same interface type as the expression
		xType := ctx.TypesInfo.TypeOf(ta.X)
		taType := ctx.TypesInfo.TypeOf(ta.Type)
		if xType == nil || taType == nil {
