func checkValSwap(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		stmts := fn.Body.List
		for i := 0; i+2 < len(stmts); i++ {
			assign1, ok1 := stmts[i].(*ast.AssignStmt)
			assign2, ok2 := stmts[i+1].(*ast.AssignStmt)
			assign3, ok3 := stmts[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			if assign1.Tok != token.DEFINE && assign1.Tok != token.ASSIGN {
				continue
			}
			if assign2.Tok != token.ASSIGN || assign3.Tok != token.ASSIGN {
				continue
			}
			if len(assign1.Lhs) != 1 || len(assign1.Rhs) != 1 {
				continue
			}
			if len(assign2.Lhs) != 1 || len(assign2.Rhs) != 1 {
				continue
			}
			if len(assign3.Lhs) != 1 || len(assign3.Rhs) != 1 {
				continue
			}
			tmp := assign1.Lhs[0]
			a := assign2.Lhs[0]
			b := assign3.Lhs[0]
			// tmp = a; a = b; b = tmp
			if exprEqual(assign1.Rhs[0], a) &&
				exprEqual(assign2.Rhs[0], b) &&
				exprEqual(assign3.Rhs[0], tmp) {
				warnings = append(warnings, warn(stmts[i].Pos(),
					"can re-write as `%s, %s = %s, %s`",
					formatNode(a), formatNode(b),
					formatNode(b), formatNode(a)))
			}
		}
		return true
	})
	return warnings
}

