func checkIfElseChain(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	p, _ := params.(*checkParams)
	minThreshold := 2
	if p != nil {
		minThreshold = p.IfElseChainMinThreshold
	}

	ast.Inspect(f, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// Count the chain length
		count := 1
		cur := ifStmt
		for {
			if cur.Else == nil {
				break
			}
			elseIf, ok := cur.Else.(*ast.IfStmt)
			if !ok {
				break
			}
			count++
			cur = elseIf
		}
		// Also count final else
		if cur.Else != nil {
			count++
		}
		if count >= minThreshold+1 {
			warnings = append(warnings, warn(ifStmt.Pos(),
				"rewrite if-else to switch statement"))
		}
		return false // Don't recurse into this if-else chain
	})
	return warnings
}

func checkImportShadow(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	importedPkgs := make(map[string]bool)
	for _, imp := range f.Imports {
		path := strings.Trim(imp.Path.Value, `"`)
		parts := strings.Split(path, "/")
		name := parts[len(parts)-1]
		if imp.Name != nil {
			name = imp.Name.Name
		}
		importedPkgs[name] = true
	}
	if len(importedPkgs) == 0 {
		return nil
	}
	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || (assign.Tok != token.DEFINE && assign.Tok != token.ASSIGN) {
			return true
		}
		for _, lhs := range assign.Lhs {
			id, ok := lhs.(*ast.Ident)
			if !ok {
				continue
			}
			if importedPkgs[id.Name] {
				warnings = append(warnings, warn(id.Pos(),
					"variable name %q shadows imported package name", id.Name))
			}
		}
		return true
	})
	return warnings
}

