func checkMapKey(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		comp, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		if _, ok := comp.Type.(*ast.MapType); !ok {
			return true
		}
		seen := make(map[string]bool)
		for _, elt := range comp.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			key := formatNode(kv.Key)
			if seen[key] {
				warnings = append(warnings, warn(kv.Key.Pos(),
					"duplicate key %s in map literal", key))
			}
			seen[key] = true
		}
		return true
	})
	return warnings
}

