func checkNewDeref(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	zeroValues := map[string]string{
		"bool":       "false",
		"int":        "0",
		"int8":       "0",
		"int16":      "0",
		"int32":      "0",
		"int64":      "0",
		"uint":       "0",
		"uint8":      "0",
		"uint16":     "0",
		"uint32":     "0",
		"uint64":     "0",
		"uintptr":    "0",
		"float32":    "0",
		"float64":    "0",
		"complex64":  "0",
		"complex128": "0",
		"string":     `""`,
		"byte":       "0",
		"rune":       "0",
	}
	ast.Inspect(f, func(n ast.Node) bool {
		unary, ok := n.(*ast.UnaryExpr)
		if !ok || unary.Op != token.MUL {
			return true
		}
		call, ok := unary.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fn, ok := call.Fun.(*ast.Ident)
		if !ok || fn.Name != "new" || len(call.Args) != 1 {
			return true
		}
		typeId, ok := call.Args[0].(*ast.Ident)
		if !ok {
			return true
		}
		if zero, ok := zeroValues[typeId.Name]; ok {
			warnings = append(warnings, warn(unary.Pos(),
				"replace `*new(%s)` with `%s`", typeId.Name, zero))
		}
		return true
	})
	return warnings
}

func checkNilValReturn(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || len(ifStmt.Body.List) == 0 {
			return true
		}
		// Check: if err == nil { return err }
		cond, ok := ifStmt.Cond.(*ast.BinaryExpr)
		if !ok || cond.Op != token.EQL {
			return true
		}
		if !isIdent(cond.Y, "nil") && !isIdent(cond.X, "nil") {
			return true
		}
		var nonNilExpr ast.Expr
		if isIdent(cond.Y, "nil") {
			nonNilExpr = cond.X
		} else {
			nonNilExpr = cond.Y
		}
		ret, ok := ifStmt.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) == 0 {
			return true
		}
		for _, r := range ret.Results {
			if exprEqual(r, nonNilExpr) {
				warnings = append(warnings, warn(ifStmt.Pos(),
					"suspicious nil return in if err == nil block"))
			}
		}
		return true
	})
	return warnings
}

