func checkReturnAfterHttpError(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		checkBlock := func(stmts []ast.Stmt) {
			for i, stmt := range stmts {
				exprStmt, ok := stmt.(*ast.ExprStmt)
				if !ok {
					continue
				}
				call, ok := exprStmt.X.(*ast.CallExpr)
				if !ok {
					continue
				}
				if !isSelector(call.Fun, "http", "Error") {
					continue
				}
				// Check next statement
				if i+1 < len(stmts) {
					if _, ok := stmts[i+1].(*ast.ReturnStmt); !ok {
						warnings = append(warnings, warn(stmt.Pos(),
							"http.Error call should be followed by return"))
					}
				}
			}
		}
		ast.Inspect(fn.Body, func(n2 ast.Node) bool {
			if b, ok := n2.(*ast.BlockStmt); ok {
				checkBlock(b.List)
			}
			return true
		})
		return true
	})
	return warnings
}

