func checkUnlambda(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		fl, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		if fl.Type.Params == nil || len(fl.Type.Params.List) == 0 {
			return true
		}
		if fl.Body == nil || len(fl.Body.List) != 1 {
			return true
		}
		ret, ok := fl.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return true
		}
		call, ok := ret.Results[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		// Check if call args match exactly the function params
		params := fl.Type.Params.List
		if len(call.Args) != countNames(params) {
			return true
		}
		i := 0
		match := true
		for _, field := range params {
			for _, name := range field.Names {
				if i >= len(call.Args) {
					match = false
					break
				}
				if !isIdent(call.Args[i], name.Name) {
					match = false
					break
				}
				i++
			}
		}
		if match {
			warnings = append(warnings, warn(fl.Pos(),
				"replace `%s` with `%s`", formatFuncLit(fl), formatNode(call.Fun)))
		}
		return true
	})
	return warnings
}

func countNames(fields []*ast.Field) int {
	count := 0
	for _, f := range fields {
		count += len(f.Names)
	}
	return count
}

func formatFuncLit(fl *ast.FuncLit) string {
	var params []string
	if fl.Type.Params != nil {
		for _, f := range fl.Type.Params.List {
			for _, n := range f.Names {
				params = append(params, n.Name+" "+formatNode(f.Type))
			}
		}
	}
	return "func(" + strings.Join(params, ", ") + ") { ... }"
}

