func checkWhyNoLint(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//nolint") {
				rest := text[len("//nolint"):]
				if rest == "" || (strings.HasPrefix(rest, ":") && !strings.Contains(rest, "//")) {
					// nolint without explanation
					if !strings.Contains(text, " ") {
						warnings = append(warnings, warn(c.Pos(),
							"nolint comment should include an explanation"))
					}
				}
			}
		}
	}
	return warnings
}

var wrapperFuncRules = []struct {
	pkg     string
	name    string
	args    []interface{} // literal values to match
	suggest string
}{
	{"wg", "Add", []interface{}{"-1"}, "wg.Done()"},
	{"strings", "Replace", []interface{}{nil, nil, nil, "-1"}, "strings.ReplaceAll"},
	{"strings", "Map", nil, ""},
}

func checkWrapperFunc(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning

	type rule struct {
		pkg     string
		fn      string
		lastArg string
		suggest string
	}

	rules := []rule{
		{"strings", "Replace", "-1", "strings.ReplaceAll"},
		{"bytes", "Replace", "-1", "bytes.ReplaceAll"},
	}

	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		pkg, name, hasPkg := getCallPkgFunc(call)
		if !hasPkg {
			// Check for wg.Add(-1)
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if ok && sel.Sel.Name == "Add" && len(call.Args) == 1 {
				if lit, ok := call.Args[0].(*ast.UnaryExpr); ok && lit.Op == token.SUB {
					if isIntLit(lit.X, "1") {
						recv := formatNode(sel.X)
						warnings = append(warnings, warn(call.Pos(),
							"use %s.Done() instead of %s.Add(-1)", recv, recv))
					}
				}
			}
			return true
		}
		for _, r := range rules {
			if pkg != r.pkg || name != r.fn {
				continue
			}
			if len(call.Args) < 4 {
				continue
			}
			lastArg := call.Args[len(call.Args)-1]
			if unary, ok := lastArg.(*ast.UnaryExpr); ok && unary.Op == token.SUB {
				if isIntLit(unary.X, "1") {
					warnings = append(warnings, warn(call.Pos(),
						"use %s method in `%s`", r.suggest, formatNode(call)))
				}
			} else if isIntLit(lastArg, "-1") {
				warnings = append(warnings, warn(call.Pos(),
					"use %s method in `%s`", r.suggest, formatNode(call)))
			}
		}
		return true
	})
	return warnings
}

func checkYodaStyleExpr(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ:
		default:
			return true
		}
		if isConstantExpr(bin.X) && !isConstantExpr(bin.Y) {
			warnings = append(warnings, warn(bin.Pos(),
				"consider to change order in expression to '%s %s %s'",
				formatNode(bin.Y), bin.Op, formatNode(bin.X)))
		}
		return true
	})
	return warnings
