func isConstantExpr(expr ast.Expr) bool {
	switch e := expr.(type) {
	case *ast.BasicLit:
		return true
	case *ast.Ident:
		return e.Name == "nil" || e.Name == "true" || e.Name == "false"
	case *ast.UnaryExpr:
		return isConstantExpr(e.X)
	}
	return false
}

func checkZeroByteRepeat(ctx *CheckContext, f *ast.File, params interface{}) []Warning {
	var warnings []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isSelector(call.Fun, "bytes", "Repeat") || len(call.Args) != 2 {
			return true
		}
		// Check if first arg is []byte{0}
		comp, ok := call.Args[0].(*ast.CompositeLit)
		if !ok {
			return true
		}
		if len(comp.Elts) == 1 {
			if isIntLit(comp.Elts[0], "0") {
				warnings = append(warnings, warn(call.Pos(),
					"use make([]byte, %s) instead of bytes.Repeat([]byte{0}, %s)",
					formatNode(call.Args[1]), formatNode(call.Args[1])))
			}
		}
		return true
	})
	return warnings
}

