package main

import (
	"flag"
	"fmt"
	"regexp"
	"strings"
	"sync"
)

// deprecated, use NewFunc instead
func OldFunc() int {
	return 0
}

type T struct {
	sync.Mutex
}

func test1() {
	// switchTrue
	x := 5
	switch true {
	case x > 3:
		fmt.Println("big")
	}

	// singleCaseSwitch
	switch x {
	case 1:
		fmt.Println("one")
	}

	// assignOp
	x = x + 1
	x = x * 2
	fmt.Println(x)
}

func test2() {
	// newDeref
	b := *new(bool)
	_ = b

	// flagDeref  
	v := *flag.Bool("v", false, "verbose")
	_ = v

	// regexpMust
	var r, _ = regexp.Compile("^[a-z]+$")
	_ = r

	// valSwap
	a, b2 := 1, 2
	tmp := a
	a = b2
	b2 = tmp
	_, _ = a, b2
}

func test3(xs []int) []int {
	// unslice
	return xs[:]
}

func test4(v interface{}) int {
	// typeSwitchVar
	switch v.(type) {
	case int:
		return v.(int)
	}
	return 0
}

func test5() {
	// wrapperFunc - sync.WaitGroup.Done
	var wg sync.WaitGroup
	wg.Add(-1)
	wg.Done()
}

func test6() string {
	// wrapperFunc - strings.ReplaceAll
	return strings.Replace("hello world", "world", "go", -1)
}

func test7(x int) string {
	// ifElseChain
	if x == 1 {
		return "one"
	} else if x == 2 {
		return "two"
	} else if x == 3 {
		return "three"
	} else {
		return "other"
	}
}
GOEOF

