					fmt.Printf("  UnaryExpr: op=%s, X=%T\n", u.Op, u.X)
				}
				if b, ok := arg.(*ast.BasicLit); ok {
					fmt.Printf("  BasicLit: kind=%s, val=%s\n", b.Kind, b.Value)
